#!/usr/bin/env bash
# SWE-Odyssey segment grader (generated by `odyssey compile`; see docs/SPEC.md section 5).
#
# Runs after the agent's turn. It trusts only what Harbor uploaded into this
# tests/ directory after the agent finished (this script, the ticket's grader,
# the segment's state.patch, the base-snapshot manifest) plus the base tarball
# once it matches that manifest. It does not trust anything the agent could
# write: the working tree, its .git, git config, or processes left running.
#
# It grades a copy, so the agent's working tree is never modified, and it
# always leaves /logs/verifier/reward.json behind: a provisional reward of 0
# with error=1 is written first, so even a crash or a Harbor-level timeout
# cannot leave the step without a reward (a missing reward file would abort
# the whole trial).
#
# reward.json holds numbers only, because Harbor parses it as
# dict[str, float | int]; the human-readable outcome goes to grade.json.
set -uo pipefail

# --- compile-time values -----------------------------------------------------
@@CONFIG@@

# --- container layout (overridable only so the script can be tested on a host) -
: "${ODYSSEY_BASE_TARBALL:=/opt/odyssey/base.tar.gz}"
: "${ODYSSEY_STATE_DIR:=/var/odyssey}"
: "${ODYSSEY_GRADER_DIR:=/var/lib/odyssey-grader}"
: "${ODYSSEY_VERIFIER_DIR:=/logs/verifier}"
: "${ODYSSEY_SCRATCH_ROOT:=/tmp}"
: "${ODYSSEY_STOP_AGENTS:=1}"
# Host tests only: restrict the process sweep to command lines containing this.
: "${ODYSSEY_SWEEP_MATCH:=}"

TESTS_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
TICKET_DIR="$TESTS_DIR/ticket"
START_DIR="$TESTS_DIR/start"
OUT="$ODYSSEY_VERIFIER_DIR"
WORK="$ODYSSEY_SCRATCH_ROOT/odyssey-grade-$ODYSSEY_POSITION"
TRUSTED="$WORK/trusted"   # base snapshot + state.patch: the segment's start tree
GRADE="$WORK/tree"        # copy of the agent's tree, then made gradeable

REWARD=0
ERROR=""
EXIT_CODE=-1
TIMED_OUT=false
PATCH_STATUS="not attempted"

export GIT_AUTHOR_NAME=grader GIT_AUTHOR_EMAIL=grader@localhost
export GIT_COMMITTER_NAME=grader GIT_COMMITTER_EMAIL=grader@localhost
# Never read git config the agent can write (~/.gitconfig, /etc/gitconfig);
# repository config is never the agent's either: every repo here is our own.
export GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null

log() { printf '[odyssey grade %s] %s\n' "$ODYSSEY_STEP" "$*" >&2; }

git_() {
    git -c safe.directory='*' -c core.hooksPath=/dev/null -c core.fsmonitor=false \
        -c commit.gpgsign=false "$@"
}

write_reward() {
    local error_flag=0
    [ -z "$ERROR" ] || error_flag=1
    printf '{"reward": %s, "error": %s}\n' "$REWARD" "$error_flag" > "$OUT/reward.json"
    printf '{"ticket": "%s", "position": %s, "reward": %s, "exit_code": %s, "timed_out": %s, "error": "%s", "segment_patch": "%s"}\n' \
        "$ODYSSEY_TICKET" "$ODYSSEY_POSITION" "$REWARD" "$EXIT_CODE" "$TIMED_OUT" "$ERROR" "$PATCH_STATUS" \
        > "$OUT/grade.json"
}

cleanup() {
    rm -rf "$WORK"
}
trap cleanup EXIT

# --- process sweep: a left-behind process could rewrite reward.json (templates/lib_sweep.sh)
@@INCLUDE lib_sweep.sh@@

# --- base snapshot manifest (templates/lib_manifest.sh) --------------------------
@@INCLUDE lib_manifest.sh@@

# --- trees ----------------------------------------------------------------------

# The segment's start tree, rebuilt from trusted inputs: never from the
# agent's .git or from anything setup.sh left behind.
prepare_trusted() {
    mkdir -p "$TRUSTED" || { ERROR="cannot create scratch dir"; return 1; }
    [ -f "$ODYSSEY_BASE_TARBALL" ] || { ERROR="base snapshot $ODYSSEY_BASE_TARBALL missing"; return 1; }
    tar -xzf "$ODYSSEY_BASE_TARBALL" -C "$TRUSTED" || { ERROR="cannot extract the base snapshot"; return 1; }
    if [ -f "$START_DIR/base.manifest" ]; then
        tree_manifest "$TRUSTED" | cmp -s - "$START_DIR/base.manifest" \
            || { ERROR="base snapshot does not match the compiled manifest"; return 1; }
    fi
    if [ -s "$START_DIR/state.patch" ]; then
        # The ceiling stops git from finding a repository above the scratch dir.
        (cd "$TRUSTED" && GIT_CEILING_DIRECTORIES="$WORK" git_ apply --whitespace=nowarn "$START_DIR/state.patch") \
            || { ERROR="state.patch does not apply to the base snapshot"; return 1; }
    fi
}

# Copy the agent's tree without any .git directory (whose config could run
# commands). Both patterns, so GNU tar and bsdtar exclude nested ones too.
copy_agent_tree() {
    case "$WORK/" in "$ODYSSEY_WORKDIR"/*) ERROR="scratch dir is inside the workdir"; return 1;; esac
    mkdir -p "$GRADE" || { ERROR="cannot create scratch dir"; return 1; }
    (cd "$ODYSSEY_WORKDIR" && tar --exclude=./.git --exclude=.git -cf - .) | (cd "$GRADE" && tar -xf -) \
        || { ERROR="copying the working tree failed"; return 1; }
}

real_parent() {
    # real_parent <rel>: make every directory on the way to $GRADE/<rel> a real
    # directory, so a symlink the agent planted cannot redirect a copy that
    # runs as root to somewhere outside the grading copy.
    local path="$GRADE" part
    local -a parts
    IFS=/ read -r -a parts <<< "$(dirname "$1")"
    for part in "${parts[@]}"; do
        [ -n "$part" ] && [ "$part" != . ] || continue
        path="$path/$part"
        if [ -L "$path" ] || { [ -e "$path" ] && [ ! -d "$path" ]; }; then rm -f "$path"; fi
        [ -d "$path" ] || mkdir "$path" || return 1
    done
}

restore_from_trusted() {
    # restore_from_trusted <rel>: $GRADE/<rel> becomes the start tree's copy, or absent.
    real_parent "$1" || return 1
    rm -rf "${GRADE:?}/$1"
    if [ -e "$TRUSTED/$1" ] || [ -L "$TRUSTED/$1" ]; then cp -a "$TRUSTED/$1" "$GRADE/$1"; fi
}

name_expression() {
    # Fill NAME_EXPR with a find expression matching any protected basename.
    local name
    NAME_EXPR=()
    while IFS= read -r name; do
        [ -n "$name" ] || continue
        [ ${#NAME_EXPR[@]} -eq 0 ] || NAME_EXPR+=(-o)
        NAME_EXPR+=(-name "$name")
    done <<EOF
$ODYSSEY_PROTECTED_NAMES
EOF
}

# Grade the agent's source changes against trusted test infrastructure:
# protected names and paths come from the start tree, and the hidden files'
# own top-level directories (absent from the start tree) are removed before
# the overlay, so nothing the agent pre-planted there survives.
make_gradeable() {
    local rel entry
    name_expression
    if [ ${#NAME_EXPR[@]} -gt 0 ]; then
        find "$GRADE" -mindepth 1 \( "${NAME_EXPR[@]}" \) -prune -exec rm -rf {} + \
            || { ERROR="removing protected names failed"; return 1; }
        while IFS= read -r rel; do
            restore_from_trusted "${rel#./}" || { ERROR="restoring $rel failed"; return 1; }
        done < <(cd "$TRUSTED" && find . -mindepth 1 \( "${NAME_EXPR[@]}" \) -prune -print)
    fi
    while IFS= read -r rel; do
        [ -n "$rel" ] || continue
        restore_from_trusted "$rel" || { ERROR="restoring $rel failed"; return 1; }
    done <<EOF
$ODYSSEY_PROTECTED_PATHS
EOF
    [ -d "$TICKET_DIR/files" ] || return 0
    for entry in "$TICKET_DIR/files"/* "$TICKET_DIR/files"/.[!.]*; do
        [ -e "$entry" ] || continue
        rel="$(basename "$entry")"
        # A directory only the hidden tests use (tests_hidden/) holds nothing of the agent's.
        if [ ! -e "$TRUSTED/$rel" ]; then rm -rf "${GRADE:?}/$rel"; fi
    done
    while IFS= read -r rel; do
        rel="${rel#./}"
        real_parent "$rel" && rm -rf "${GRADE:?}/$rel" && cp -a "$TICKET_DIR/files/$rel" "$GRADE/$rel" \
            || { ERROR="overlaying hidden test files failed"; return 1; }
    done < <(cd "$TICKET_DIR/files" && find . \( -type f -o -type l \) -print)
}

# Run the ticket's grader with a deadline below the verifier timeout.
run_grader() {
    if command -v timeout >/dev/null 2>&1; then
        (cd "$GRADE" && ODYSSEY_OUT="$OUT" timeout -k 10 "$ODYSSEY_RUN_TIMEOUT_SEC" bash "$TICKET_DIR/run.sh")
    else
        (cd "$GRADE" && ODYSSEY_OUT="$OUT" bash "$TICKET_DIR/run.sh")
    fi
    EXIT_CODE=$?
    if [ "$EXIT_CODE" -eq 0 ]; then
        REWARD=1
    elif [ "$EXIT_CODE" -eq 124 ] || [ "$EXIT_CODE" -eq 137 ]; then
        TIMED_OUT=true
        ERROR="run.sh timed out after ${ODYSSEY_RUN_TIMEOUT_SEC}s"
    fi
}

# --- segment diff -----------------------------------------------------------------

snapshot_repo() {
    # snapshot_repo <git-dir> <tree>: a new bare repository whose HEAD is <tree>.
    local repo="$1" tree="$2" t c
    rm -rf "$repo"
    git_ init -q --bare "$repo" || return 1
    (
        cd "$tree" &&
            GIT_INDEX_FILE="$WORK/snapshot.index" git_ --git-dir="$repo" --work-tree=. add -A &&
            t="$(GIT_INDEX_FILE="$WORK/snapshot.index" git_ --git-dir="$repo" write-tree)" &&
            c="$(git_ --git-dir="$repo" commit-tree "$t" -m start)" &&
            git_ --git-dir="$repo" update-ref HEAD "$c"
    )
}

# The agent's changes against the segment start, untracked files included,
# memory files excluded (they are carried state, not work on the ticket).
# Reset policies diff against the trusted start tree; carry against the tree
# the previous segment's grader saw, kept in a repository of the grader's own.
write_segment_patch() {
    local repo="$WORK/start.git" f
    local -a pathspec=(.)
    while IFS= read -r f; do
        [ -n "$f" ] && pathspec+=(":(exclude,literal,top)$f")
    done <<EOF
$ODYSSEY_MEMORY_FILES
EOF
    if [ "$ODYSSEY_CODE_STATE" = carry ]; then
        repo="$ODYSSEY_GRADER_DIR/carry.git"
        if [ "$ODYSSEY_POSITION" = 1 ] || [ ! -d "$repo" ]; then
            [ "$ODYSSEY_POSITION" = 1 ] || log "carried snapshot missing; diffing against the base"
            mkdir -p "$ODYSSEY_GRADER_DIR" && chmod 700 "$ODYSSEY_GRADER_DIR" 2>/dev/null
            snapshot_repo "$repo" "$TRUSTED" || { PATCH_STATUS="cannot snapshot the start tree"; return 0; }
        fi
    else
        snapshot_repo "$repo" "$TRUSTED" || { PATCH_STATUS="cannot snapshot the start tree"; return 0; }
    fi
    if (
        cd "$GRADE" &&
            export GIT_INDEX_FILE="$WORK/agent.index" &&
            git_ --git-dir="$repo" --work-tree=. read-tree HEAD &&
            git_ --git-dir="$repo" --work-tree=. add -A &&
            git_ --git-dir="$repo" --work-tree=. diff --cached --binary HEAD -- "${pathspec[@]}" > "$OUT/segment.patch" &&
            if [ "$ODYSSEY_CODE_STATE" = carry ]; then
                t="$(git_ --git-dir="$repo" write-tree)" &&
                    c="$(git_ --git-dir="$repo" commit-tree "$t" -p HEAD -m "end of segment $ODYSSEY_POSITION")" &&
                    git_ --git-dir="$repo" update-ref HEAD "$c"
            fi
    ); then
        PATCH_STATUS="ok"
    else
        PATCH_STATUS="git diff failed"
    fi
}

# Tell later segments whether this one was accepted.
write_feedback() {
    [ "$ODYSSEY_FEEDBACK" = binary ] || return 0
    local verdict=rejected
    [ "$REWARD" = 1 ] && verdict=accepted
    mkdir -p "$ODYSSEY_STATE_DIR/feedback" &&
        printf '%s\n' "$verdict" > "$ODYSSEY_STATE_DIR/feedback/$ODYSSEY_POSITION.txt"
}

main() {
    mkdir -p "$OUT"
    ERROR="grader did not finish"
    write_reward
    ERROR=""

    sweep_processes
    rm -rf "$WORK"
    if [ ! -f "$TICKET_DIR/run.sh" ]; then
        ERROR="ticket run.sh missing from the step's tests"
    elif prepare_trusted && copy_agent_tree; then
        write_segment_patch       # before the grading copy is changed
        if make_gradeable; then
            run_grader
        fi
    fi
    write_feedback || log "could not write feedback"
    write_reward
    log "ticket $ODYSSEY_TICKET: reward $REWARD (exit $EXIT_CODE${ERROR:+, $ERROR})"
    # The scratch copies are removed by the EXIT trap.
}

main "$@"
